// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address token, uint256 tokenId, uint256 fee, bytes calldata data) public {
        vm.assume(token != address(0));
        vm.assume(token != address(c));
        // Deploy a minimal ERC721 that returns the callback selector from its safe transfers
        MockERC721 nft = new MockERC721();
        nft.mint(tokenId);
        // Initialize c with minimal required state
        // We use the public `nft` state slot directly via the re-initialization cheat
        // But we don't need to call initialize; we just need the token being flash loaned to be owned by c.
        // Transfer the token to c so availableForFlashLoan passes
        nft.unsafeSetOwner(address(c), tokenId);
        FlashLoanReceiver receiver = new FlashLoanReceiver();
        // The flashLoan function calls onERC721Received on the receiver which calls back onERC721Received on the token.
        // The token needs to implement onERC721Received to return the selector or the buggy value.
        // Instead, the internal call to ERC721(token).safeTransferFrom triggers the receiver's onERC721Received callback
        // which must return the expected selector in the original, but the buggy contract returns bytes4(0xdeadbeef)
        // So we observe whether the flashLoan succeeds.
        bool success = true;
        try this.helperFlashLoan(c, receiver, address(nft), tokenId, fee, data) {
            success = true;
        } catch {
            success = false;
        }
        // If the receiver returns the correct selector, flashLoan should succeed. If it returns deadbeef, it fails.
        // The property: flashLoan always succeeds when the receiver returns onERC721Received.selector (which the original always does).
        // With buggy version, deadbeef breaks the flash loan.
        assertTrue(success);
    }

    function helperFlashLoan(C _c, FlashLoanReceiver receiver, address token, uint256 tokenId, uint256 fee, bytes calldata data) external {
        vm.deal(address(receiver), fee + 1);
        vm.prank(address(receiver));
        // receiver will call flashLoan with value
        _c.flashLoan{value: fee + 1}(IERC3156FlashBorrower(address(receiver)), token, tokenId, data);
    }
}

contract MockERC721 {
    mapping(uint256 => address) private _owners;
    function mint(uint256 id) external {
        _owners[id] = msg.sender;
    }
    function unsafeSetOwner(address owner, uint256 id) external {
        _owners[id] = owner;
    }
    function ownerOf(uint256 id) external view returns (address) {
        return _owners[id];
    }
    function safeTransferFrom(address, address to, uint256 id) external {
        _owners[id] = to;
    }
    function safeTransferFrom(address, address to, uint256 id, bytes calldata) external {
        _owners[id] = to;
    }
    function transferFrom(address, address to, uint256 id) external {
        _owners[id] = to;
    }
}

contract FlashLoanReceiver is IERC3156FlashBorrower {
    function onFlashLoan(address, address, uint256, uint256, bytes calldata) external view returns (bytes32) {
        return keccak256("onFlashLoan");
    }
    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        // This returns the correct selector in the original, but the buggy version is changed here.
        // The buggy C changes the behavior: its onERC721Received returns deadbeef, so the flashLoan's
        // safeTransferFrom check fails. To simulate that, we would need the attack to be inside the receiver,
        // but the receiver is the one calling flashLoan, not the token. The token safeTransferFrom triggers
        // the receiver's onERC721Received which returns the selector. If C's onERC721Received is buggy,
        // it doesn't matter because the receiver's callback is what's checked. The bug is in C's own
        // onERC721Received, but that is only used when someone transfers TO C. Here, C transfers FROM itself,
        // so the receiver's callback is checked. The bug is dormant for flashLoan. So we need a call that
        // exercises C's onERC721Received. That is done by safeTransferFrom or _safeMint to C.
        // So we can call safeTransferFrom on the token to C and see if it reverts.
        return 0x150b7a02; // correct selector
    }
}

