pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint256 tokenId, bytes calldata data) public {
        // Bound tokenId to avoid zero-address revert in _mint
        tokenId = bound(tokenId, 1, type(uint256).max);

        // Deploy a receiver that returns the selector on onFlashLoan
        FlashLoanReceiver receiver = new FlashLoanReceiver();

        // Set up c: mint an NFT to c itself so it can flash loan it
        // We need to initialize c and mint an NFT to it. We'll deploy a minimal NFT and set it on c.
        // But c's constructor sets factory, royaltyRegistry, stolenNftOracle.
        // We'll use the default NFT as address(this) simulates an NFT that implements ownerOf returning address(this).
        // Since availableForFlashLoan requires ownerOf(token) == address(this), we need the token to return address(this) as owner.
        // We'll use a helper NFT contract that returns address(this) as owner of any tokenId.
        MockNFT nft = new MockNFT();
        // We need to re-deploy c with the correct args? No, setUp uses fixed args, but we can still use the nft.
        // availableForFlashLoan uses ERC721(token).ownerOf(tokenId). We can't change c's nft.
        // We'll just call flashLoan passing the mock NFT as token parameter.
        // The flashLoan function calls ERC721(token).safeTransferFrom, which will call onERC721Received on the receiver.
        // The receiver's onERC721Received returns the buggy/mutant value (if the mutant is used).
        // In the reference, the receiver's onERC721Received returns selector, so safeTransferFrom succeeds.

        // We need to ensure availableForFlashLoan returns true. Since the token we pass is the mock NFT,
        // its ownerOf returns address(this) (since we deploy it), but c is not the owner. We need c to own the token.
        // We can mint tokenId to c on the mock NFT.
        nft.mint(address(c), tokenId);

        // Now flashLoan should work. We need to pay the fee if baseToken == address(0) (ETH).
        // Since baseToken is not set (address(0) by default), flashLoan requires msg.value >= fee.
        // fee = changeFee (default 0). So msg.value >= 0.
        // We'll send 0 ETH.
        vm.prank(address(this));
        vm.deal(address(this), 0);
        bool success = c.flashLoan(IERC3156FlashBorrower(address(receiver)), address(nft), tokenId, data);

        // The property: flashLoan must return true when onFlashLoan succeeds.
        // The mutant's onERC721Received causes safeTransferFrom to revert, so flashLoan reverts before returning,
        // or returns false? Actually flashLoan calls ERC721(token).safeTransferFrom which calls onERC721Received.
        // If onERC721Received returns wrong selector, safeTransferFrom reverts, so flashLoan reverts entirely.
        // Thus the reference returns true (no revert), the mutant does revert.
        // We assert true for reference, but mutant reverts (caught as false by try/catch).
        // We'll use try/catch to observe revert.
        // But the assertion must be exactly one. We'll do:
        // assertTrue(success);
        // However, if the mutant reverts, success is never set, and the call itself reverts.
        // We need to catch the revert and assert that it succeeded (didn't revert).
        // So:
        bool ok;
        try c.flashLoan(IERC3156FlashBorrower(address(receiver)), address(nft), tokenId, data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract MockNFT {
    mapping(uint256 => address) public ownerOf;
    function mint(address to, uint256 id) external {
        ownerOf[id] = to;
    }
    // ERC721 safeTransferFrom minimal implementation
    function safeTransferFrom(address from, address to, uint256 id) external {
        require(from == ownerOf[id], "WRONG_FROM");
        require(to != address(0), "INVALID_RECIPIENT");
        ownerOf[id] = to;
        // Call onERC721Received on the receiver
        if (to.code.length > 0) {
            require(
                IERC721Receiver(to).onERC721Received(msg.sender, from, id, "") == 0x150b7a02,
                "UNSAFE_RECIPIENT"
            );
        }
    }
}

interface IERC721Receiver {
    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4);
}

contract FlashLoanReceiver is IERC3156FlashBorrower, IERC721Receiver {
    function onFlashLoan(
        address,
        address,
        uint256,
        uint256,
        bytes calldata
    ) external override returns (bytes32) {
        return keccak256("onFlashLoan");
    }

    // This is the function that differs in the mutant: returns selector in reference, 0xdeadbeef in mutant.
    // The test must use the deployed contract's implementation. The mutant changes the original contract's
    // ERC721TokenReceiver base contract. Since we deploy the receiver separately, it will always return the
    // correct selector. Wait, the bug is in the original contract P's `onERC721Received`! Not in the receiver.
    // The flashLoan function calls ERC721(token).safeTransferFrom, which calls token's onERC721Received?
    // No, safeTransferFrom on ERC721 calls the receiver's onERC721Received, not the contract's own.
    // The mutant changes P's own ERC721TokenReceiver.onERC721Received, which is used when P receives ERC721 tokens.
    // The flashLoan flow: c calls nft.safeTransferFrom(address(this), receiver, tokenId).
    // The nft then calls receiver.onERC721Received(...). The receiver is the FlashLoanReceiver, not c.
    // So the mutant's change to c's onERC721Received does not affect the flashLoan call directly.
    // Wait, the mutant changes the abstract contract ERC721TokenReceiver which is inherited by C.
    // So c's onERC721Received returns 0xdeadbeef. But is c's onERC721Received called during flashLoan?
    // In flashLoan, after the flash loan, it calls ERC721(token).safeTransferFrom(receiver, address(this), tokenId).
    // The nft calls address(this).onERC721Received(...), which is c.onERC721Received.
    // If c.onERC721Received returns 0xdeadbeef, the require in safeTransferFrom (which checks for selector) fails,
    // causing flashLoan to revert.
    // In the reference, c.onERC721Received returns the selector, so it succeeds.
    // So the property is: flashLoan does not revert when the callback returns the correct selector.
    // The receiver must still return the correct onFlashLoan selector to make onFlashLoan succeed.
    // So we need the receiver to implement onFlashLoan returning the correct selector, and onERC721Received
    // returning something (but it is not called in the flow? Actually the receiver is the flash borrower,
    // it receives the NFT temporarily. The nft calls receiver.onERC721Received. That is the flash loan receiver,
    // NOT c. Wait, the flow:
    // 1. c.flashLoan calls nft.safeTransferFrom(address(this), receiver, tokenId) -- this triggers nft calling receiver.onERC721Received.
    // 2. Then receiver.onFlashLoan is called.
    // 3. Then nft.safeTransferFrom(receiver, address(this), tokenId) -- this triggers nft calling c.onERC721Received (because address(this) is c).
    // So c.onERC721Received is called! And the mutant changes its return value, so the third step fails.
    // Thus our test must ensure that the receiver's onFlashLoan returns the correct selector (keccak256("onFlashLoan"))
    // and that the receiver's onERC721Received (which is called during step 1) returns the correct selector.
    // We'll implement the receiver to return the correct selector for onERC721Received.
    // That way, the only difference is c.onERC721Received.

    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external override returns (bytes4) {
        return 0x150b7a02;
    }
}

interface IERC3156FlashBorrower {
    function onFlashLoan(
        address initiator,
        address token,
        uint256 amount,
        uint256 fee,
        bytes calldata data
    ) external returns (bytes32);
}

