pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint256 tokenId, uint256 fee) public {
        // Bound tokenId to a reasonable range to avoid collisions
        vm.assume(tokenId > 0 && tokenId < 1000);
        // Fee must be payable and non-trivial
        fee = bound(fee, 1, 100 ether);

        // Deploy a mock ERC721 that mints the token to c and supports safeTransferFrom
        MockERC721 nft = new MockERC721();
        nft.mint(address(c), tokenId);

        // Initialize c with the mock NFT and zero fees (changeFee = 0 for simplicity)
        c.initialize(address(0), address(nft), 100 ether, 100 ether, 0, 0, bytes32(0), false, false);
        // Give c some base token (ETH) to pay fees if needed
        vm.deal(address(c), fee);

        // Deploy a mock flash loan receiver that returns the correct onFlashLoan selector
        MockReceiver receiver = new MockReceiver();

        // Fund the test contract to pay the flash fee
        vm.deal(address(this), fee + 1 ether);

        // Call flashLoan — it should succeed (not revert) on the reference contract
        bool success;
        try c.flashLoan{value: fee}(IERC3156FlashBorrower(address(receiver)), address(nft), tokenId, "") returns (bool result) {
            success = result;
        } catch {
            success = false;
        }

        // The reference must succeed (return true); the bug returns 0xdeadbeef causing safeTransferFrom to revert
        assertTrue(success);
    }
}

contract MockERC721 {
    mapping(uint256 => address) private _owner;
    mapping(uint256 => address) private _operatorApprovals;

    function ownerOf(uint256 tokenId) external view returns (address) {
        return _owner[tokenId];
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        // simple mock: just transfer ownership
        require(_owner[tokenId] == from, "wrong from");
        _owner[tokenId] = to;
        // If to is a contract, call onERC721Received
        if (to.code.length > 0) {
            (bool success, bytes memory ret) = to.call(abi.encodeWithSignature("onERC721Received(address,address,uint256,bytes)", msg.sender, from, tokenId, ""));
            require(success, "callback failed");
            require(ret.length == 32 && abi.decode(ret, (bytes4)) == 0x150b7a02, "wrong callback");
        }
    }

    function mint(address to, uint256 tokenId) external {
        require(_owner[tokenId] == address(0), "already minted");
        _owner[tokenId] = to;
    }

    function approve(address to, uint256 tokenId) external {
        _operatorApprovals[tokenId] = to;
    }

    function getApproved(uint256 tokenId) external view returns (address) {
        return _operatorApprovals[tokenId];
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x80ac58cd;
    }
}

